(function(){'use strict';
const KEY='safariPocketbookBookings',tabs=[...document.querySelectorAll('[data-booking-tab]')],panels=[...document.querySelectorAll('[data-booking-panel]')],count=document.getElementById('bookingCount'),records=document.getElementById('bookingRecords');
if(!tabs.length)return;
const esc=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const read=()=>{try{const value=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(value)?value:[]}catch(error){return[]}};
const write=value=>localStorage.setItem(KEY,JSON.stringify(value));
function toast(message){const node=document.getElementById('toast');node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),2200)}
function show(name){tabs.forEach(tab=>{const active=tab.dataset.bookingTab===name;tab.classList.toggle('selected',active);tab.setAttribute('aria-selected',String(active))});panels.forEach(panel=>{const active=panel.dataset.bookingPanel===name;panel.hidden=!active;panel.classList.toggle('active',active)});document.querySelector('.booking-shell')?.scrollIntoView({block:'start'})}
tabs.forEach(tab=>tab.addEventListener('click',()=>show(tab.dataset.bookingTab)));
const today=new Date().toISOString().slice(0,10);['flightDepart','flightReturn','stayCheckin','stayCheckout','recordDate'].forEach(id=>document.getElementById(id).min=today);
document.querySelectorAll('[data-go="bookings"]').forEach(button=>button.addEventListener('click',()=>{try{const trip=JSON.parse(localStorage.getItem('safariPocketbookTrip')||'null');if(!trip)return;const destination=trip.countries?.join(', ')||trip.stops?.[0]?.name||'';if(!document.getElementById('flightTo').value)document.getElementById('flightTo').value=destination;if(!document.getElementById('stayDestination').value)document.getElementById('stayDestination').value=destination;if(trip.startDate&&!document.getElementById('flightDepart').value)document.getElementById('flightDepart').value=trip.startDate;if(trip.startDate&&!document.getElementById('stayCheckin').value)document.getElementById('stayCheckin').value=trip.startDate}catch(error){}}));
function openSearch(url){const opened=window.open(url,'_blank','noopener');if(!opened)location.href=url}
document.getElementById('flightSearchForm').addEventListener('submit',event=>{event.preventDefault();const from=document.getElementById('flightFrom').value.trim(),to=document.getElementById('flightTo').value.trim(),depart=document.getElementById('flightDepart').value,back=document.getElementById('flightReturn').value,travellers=document.getElementById('flightTravellers').value;if(back&&back<depart){toast('Return date must be after departure.');return}const query=`Flights from ${from} to ${to} departing ${depart}${back?` returning ${back}`:''} for ${travellers} traveller${travellers==='1'?'':'s'}`;openSearch(`https://www.google.com/travel/flights?q=${encodeURIComponent(query)}`)});
document.getElementById('staySearchForm').addEventListener('submit',event=>{event.preventDefault();const destination=document.getElementById('stayDestination').value.trim(),checkin=document.getElementById('stayCheckin').value,checkout=document.getElementById('stayCheckout').value,guests=document.getElementById('stayGuests').value,type=document.getElementById('stayType').value;if(checkout<=checkin){toast('Check-out must be after check-in.');return}const query=`${type} in ${destination} check in ${checkin} check out ${checkout} for ${guests} guest${guests==='1'?'':'s'}`;openSearch(`https://www.google.com/travel/search?q=${encodeURIComponent(query)}`)});
function render(){const items=read();count.textContent=items.length;records.innerHTML=items.length?items.map(item=>`<article><span>${esc(item.type).toUpperCase()}</span><h3>${esc(item.provider)}</h3><p><strong>Reference:</strong> ${esc(item.reference)}${item.date?` · ${esc(item.date)}`:''}</p>${item.details?`<small>${esc(item.details)}</small>`:''}<button type="button" data-delete-booking="${esc(item.id)}" aria-label="Delete booking with ${esc(item.provider)}">Remove</button></article>`).join(''):'<div class="booking-empty"><strong>No confirmed bookings saved.</strong><p>Flight and stay searches do not create records automatically. Add a reference only after confirmation by the provider.</p></div>'}
document.getElementById('bookingRecordForm').addEventListener('submit',event=>{event.preventDefault();const items=read();items.unshift({id:`${Date.now()}-${Math.random().toString(16).slice(2)}`,type:document.getElementById('recordType').value,provider:document.getElementById('recordProvider').value.trim().slice(0,120),reference:document.getElementById('recordReference').value.trim().slice(0,120),date:document.getElementById('recordDate').value,details:document.getElementById('recordDetails').value.trim().slice(0,1000)});write(items);event.target.reset();render();toast('Confirmed booking saved on this device.')});
records.addEventListener('click',event=>{const button=event.target.closest('[data-delete-booking]');if(!button||!confirm('Remove this booking record from the device?'))return;write(read().filter(item=>item.id!==button.dataset.deleteBooking));render();toast('Booking record removed.')});
render();
})();
